<?php if ( ! defined( 'ABSPATH' ) ) { exit; }
$user = $args['user']; $type = 'analyst-request' === $args['view'] ? 'analyst' : 'situation';
$application = Revayat_Companion_Member_Applications::latest( $user->ID, $type ); $state = Revayat_Companion_Member_Applications::state( $application );
$profile = Revayat_Companion_Member_Profile::get( $user->ID );
$data = $application ? (array) get_post_meta( $application->ID, '_rv_payload', true ) : $profile;
// Supplement editable drafts; never alter the snapshot of a submitted application.
if ( ! in_array( $state, array( 'pending', 'approved' ), true ) ) {
	foreach ( array( 'full_name', 'role_title', 'organization', 'expertise', 'bio' ) as $field ) {
		if ( ! array_key_exists( $field, $data ) || ( in_array( $field, array( 'full_name', 'expertise', 'bio' ), true ) && '' === trim( (string) $data[ $field ] ) ) ) { $data[ $field ] = $profile[ $field ] ?? ''; }
	}
}
$professional_complete = mb_strlen( trim( $data['full_name'] ?? '' ) ) >= 3 && '' !== trim( $data['expertise'] ?? '' ) && mb_strlen( trim( $data['bio'] ?? '' ) ) >= 30;
$documents = $application ? (array) get_post_meta( $application->ID, '_rv_documents', true ) : array();
if ( in_array( $state, array( 'rejected', 'withdrawn', 'revoked' ), true ) ) { $documents = array(); }
$blocked = 'situation' === $type && ! Revayat_Companion_Private_Documents::ready();
$editable = ! in_array( $state, array( 'pending', 'approved' ), true ); ?>
<?php if ( 'draft' === $state && 'draft' === ( $_GET['saved'] ?? '' ) ) : ?><p class="rv-member-notice" role="status">پیش‌نویس ذخیره شد؛ هنوز برای بررسی ارسال نشده است. پس از تکمیل اطلاعات، «ارسال برای بررسی» را بزنید.</p><?php endif; ?>
<section class="rv-member-card" data-application-type="<?php echo esc_attr( $type ); ?>"><h2><?php echo 'analyst' === $type ? 'مسیر عضویت در شبکه تحلیلگران' : 'مدارک و شرایط دسترسی ویژه'; ?></h2><p><?php echo 'analyst' === $type ? 'حوزه تخصص و معرفی حرفه‌ای شما بررسی می‌شود. نتیجه و توضیحات بررسی در همین صفحه و اعلان‌های پنل نمایش داده می‌شود. این درخواست، دسترسی اتاق وضعیت ایجاد نمی‌کند.' : 'نام کامل، کد ملی، عکس پرسنلی و تصویر کارت ملی برای بررسی لازم‌اند. این مدارک عمومی نمی‌شوند و عکس پرسنلی جایگزین تصویر پروفایل شما نخواهد شد.'; ?></p><ol class="rv-member-steps"><li>تکمیل اطلاعات</li><li>ارسال برای بررسی</li><li>اعلام نتیجه</li></ol><p><span class="rv-member-badge" data-application-state><?php echo esc_html( Revayat_Companion_Member_Applications::labels()[ $state ] ); ?></span></p>
<?php if ( $blocked ) : ?><p class="rv-member-notice">ارسال درخواست دسترسی به اتاق وضعیت فعلاً در دسترس نیست. در حال حاضر نیازی به ارسال مدارک ندارید.</p><?php endif; ?>
<?php if ( $application && get_post_meta( $application->ID, '_rv_feedback', true ) ) : ?><div class="rv-member-notice"><strong>توضیح بررسی</strong><p><?php echo esc_html( get_post_meta( $application->ID, '_rv_feedback', true ) ); ?></p></div><?php endif; ?>
<?php if ( 'approved' === $state ) : ?><a class="rv-member-button" href="<?php echo esc_url( 'analyst' === $type ? home_url( '/dashboard/?view=note-edit' ) : get_post_type_archive_link( 'situation_room' ) ); ?>"><?php echo 'analyst' === $type ? 'نوشتن یادداشت' : 'ورود به اتاق وضعیت'; ?></a><?php endif; ?></section>
<?php if ( $editable && ! $blocked ) : ?><form class="rv-member-card rv-member-form" data-rv-form data-dirty-guard data-application-form="<?php echo esc_attr( $type ); ?>" method="post" enctype="multipart/form-data" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="revayat_member_application"><?php wp_nonce_field( 'rv_application', 'rv_nonce' ); ?><input type="hidden" name="type" value="<?php echo esc_attr( $type ); ?>"><input type="hidden" name="version" value="<?php echo esc_attr( $application ? get_post_meta( $application->ID, '_rv_version', true ) : 0 ); ?>">
<?php if ( 'analyst' === $type ) : ?>
<p><?php echo $professional_complete ? 'اطلاعات حرفه‌ای شما آماده است. آن را مرور کنید و در صورت تمایل نمونه تحلیل اضافه کنید.' : 'اطلاعات قبلی شما وارد شده است؛ فقط موارد ناقص را همین‌جا تکمیل کنید. نیازی به رفتن به صفحه پروفایل نیست.'; ?></p>
<details class="rv-application-profile" <?php if ( ! $professional_complete ) { echo 'open'; } ?>>
<summary>اطلاعات حرفه‌ای — <?php echo $professional_complete ? 'مرور و ویرایش' : 'تکمیل اطلاعات'; ?></summary>
<?php if ( $professional_complete ) : ?><p><?php echo esc_html( $data['full_name'] . ' · ' . $data['expertise'] ); ?></p><?php endif; ?>
<?php endif; ?>
<div class="rv-member-fields"><label>نام و نام خانوادگی<input name="full_name" minlength="3" maxlength="160" value="<?php echo esc_attr( $data['full_name'] ?? '' ); ?>" required></label>
<?php if ( 'analyst' === $type ) : ?><?php foreach ( array( 'role_title' => 'عنوان شغلی (اختیاری)', 'organization' => 'سازمان (اختیاری)', 'expertise' => 'حوزه تخصصی' ) as $key => $label ) : ?><label><?php echo esc_html( $label ); ?><input name="<?php echo esc_attr( $key ); ?>" value="<?php echo esc_attr( $data[ $key ] ?? '' ); ?>" <?php echo 'expertise' === $key ? 'required' : ''; ?> type="text" maxlength="500"></label><?php endforeach; ?><label class="rv-span-all">معرفی حرفه‌ای و سوابق<textarea name="bio" required minlength="30" maxlength="3000" rows="5"><?php echo esc_textarea( $data['bio'] ?? '' ); ?></textarea></label>
<small class="rv-span-all">حوزه فعالیت، تجربه مرتبط و سوابق تحلیلی خود را توضیح دهید؛ حداقل ۳۰ نویسه. این اطلاعات مبنای بررسی درخواست است.</small></div></details>
<label>پیوند نمونه تحلیل (اختیاری)<input name="sample_url" type="url" maxlength="500" value="<?php echo esc_attr( $data['sample_url'] ?? '' ); ?>" placeholder="https://" dir="ltr"><small>پیوند یک نوشته یا تحلیل منتشرشده برای ارزیابی بهتر سوابق شما.</small></label>
<p><small>ویرایش این فرم فقط در همین درخواست ذخیره می‌شود؛ اطلاعات پروفایل شما جداگانه قابل ویرایش است.</small></p>
<?php else : ?><label>کد ملی<input name="national_id" <?php if ( empty( $documents ) ) { echo 'required'; } ?> inputmode="numeric" maxlength="10" data-digits autocomplete="off"><small><?php echo ! empty( $documents ) ? 'اگر تغییر نکرده، این فیلد را خالی بگذارید.' : '۱۰ رقم؛ صفر ابتدای کد را حفظ کنید.'; ?></small></label><?php foreach ( array( 'portrait' => 'عکس پرسنلی', 'national_card' => 'تصویر کارت ملی' ) as $field => $label ) : ?><label><?php echo esc_html( $label ); ?><input type="file" name="<?php echo esc_attr( $field ); ?>" <?php if ( empty( $documents[ $field ] ) ) { echo 'required'; } ?> accept="image/jpeg,image/png,image/webp"><small>JPG، PNG یا WebP؛ حداکثر ۵ مگابایت. <?php echo ! empty( $documents[ $field ] ) ? 'فایل قبلی ثبت شده؛ انتخاب فایل تازه آن را جایگزین می‌کند.' : ''; ?></small></label><?php endforeach; ?><label class="rv-span-all">دلیل درخواست (اختیاری)<textarea name="reason" maxlength="500" rows="4"><?php echo esc_textarea( $data['reason'] ?? '' ); ?></textarea></label><p class="rv-span-all">مدت نگهداری مدارک پس از تصمیم: <?php echo esc_html( revayat_en2fa( get_option( 'revayat_document_retention_days' ) ) ); ?> روز؛ پیش‌نویس رهاشده: <?php echo esc_html( revayat_en2fa( get_option( 'revayat_document_draft_days' ) ) ); ?> روز. سابقه تصمیم بدون تصویر باقی می‌ماند.</p></div><?php endif; ?>
<label class="rv-member-check"><input type="checkbox" name="consent" value="1" required>صحت اطلاعات و <?php echo 'analyst' === $type ? 'نمایش اطلاعات حرفه‌ای پس از تأیید را می‌پذیرم.' : 'استفاده خصوصی از مدارک برای بررسی این درخواست با مدت نگهداری اعلام‌شده را می‌پذیرم.'; ?></label><p data-form-status role="status" aria-live="polite" hidden></p><a data-application-track class="rv-member-secondary" href="<?php echo esc_url( home_url( '/dashboard/?view=' . $args['view'] ) ); ?>" hidden>پیگیری درخواست</a><div class="rv-member-actions"><button class="rv-member-button" name="mode" value="submit">ارسال برای بررسی</button><button class="rv-member-secondary" name="mode" value="draft" formnovalidate>ذخیره پیش‌نویس</button></div></form><?php endif; ?>
<?php if ( $application ) : ?><section class="rv-member-card"><h2>تاریخچه درخواست</h2><ol><?php foreach ( get_post_meta( $application->ID, '_rv_history', false ) as $event ) : ?><li><strong><?php echo esc_html( Revayat_Companion_Member_Applications::labels()[ $event['to'] ] ?? '' ); ?></strong> — <?php echo esc_html( $event['at'] ); ?><?php if ( $event['reason'] ) : ?><p><?php echo esc_html( $event['reason'] ); ?></p><?php endif; ?></li><?php endforeach; ?></ol><?php if ( in_array( $state, array( 'draft', 'pending', 'needs_changes' ), true ) ) : ?><form data-rv-form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'rv_application', 'rv_nonce' ); ?><input type="hidden" name="action" value="revayat_member_application"><input type="hidden" name="type" value="<?php echo esc_attr( $type ); ?>"><input type="hidden" name="version" value="<?php echo esc_attr( get_post_meta( $application->ID, '_rv_version', true ) ); ?>"><input type="hidden" name="mode" value="withdraw"><p data-form-status role="status" hidden></p><button class="rv-member-secondary">انصراف از درخواست</button></form><?php endif; ?></section><?php endif; ?>
